export function getSheikahGlyph(char) {
  if (!char) return null;
  // Normalize accents: é -> e, à -> a, etc.
  const normalized = char.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  return SHEIKAH_DICT[normalized] || null;
}

/**
 * Returns list of all supported characters.
 */
export function getSupportedChars() {
  return Object.keys(SHEIKAH_DICT);
}

// Make accessible on window object if used without modules
if (typeof window !== 'undefined') {
  window.SHEIKAH_DICT = SHEIKAH_DICT;
  window.getSheikahGlyph = getSheikahGlyph;
  window.getSupportedChars = getSupportedChars;
}
